#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define pb push_back
const int mod = 998244353;
const int root = 15311432;
const int root_1 = 469870224;
const int root_pw = 1 << 23;
const int N = 400004;

vector<int> v[N];

ll modInv(ll a, ll mod = mod){
	ll x0 = 0, x1 = 1, r0 = mod, r1 = a;
	while(r1){
		ll q = r0 / r1;
		x0 -= q * x1; swap(x0, x1);
		r0 -= q * r1; swap(r0, r1);
	}
	return x0 < 0 ? x0 + mod : x0;
}

void fft (vector<int> &a, bool inv) {
	int n = (int) a.size();

	for (int i=1, j=0; i<n; ++i) {
		int bit = n >> 1;
		for (; j>=bit; bit>>=1)
			j -= bit;
		j += bit;
		if (i < j)
			swap (a[i], a[j]);
	}

	for (int len=2; len<=n; len<<=1) {
		int wlen = inv ? root_1 : root;
		for (int i=len; i<root_pw; i<<=1)
			wlen = int (wlen * 1ll * wlen % mod);
		for (int i=0; i<n; i+=len) {
			int w = 1;
			for (int j=0; j<len/2; ++j) {
				int u = a[i+j],  v = int (a[i+j+len/2] * 1ll * w % mod);
				a[i+j] = u+v < mod ? u+v : u+v-mod;
				a[i+j+len/2] = u-v >= 0 ? u-v : u-v+mod;
				w = int (w * 1ll * wlen % mod);
			}
		}
	}

	if(inv) {
		int nrev = modInv(n, mod);
		for (int i=0; i<n; ++i)
			a[i] = int (a[i] * 1ll * nrev % mod);
	}
}

void pro(const vector<int> &a, const vector<int> &b, vector<int> &res) {
	vector<int> fa(a.begin(), a.end()),  fb(b.begin(), b.end());
	int n = 1;
	while (n < (int) max(a.size(), b.size()))  n <<= 1;
	n <<= 1;
	fa.resize (n),  fb.resize (n);

	fft(fa, false), fft (fb, false);
	for (int i = 0; i < n; ++i)
		fa[i] = 1LL * fa[i] * fb[i] % mod;
	fft (fa, true);
	res = fa;
}

int S(int n, int r) {

	int nn = 1;
	while(nn < n) nn <<= 1;

	for(int i = 0; i < n; ++i) {
		v[i].push_back(i);
		v[i].push_back(1);
	}
	for(int i = n; i < nn; ++i) {
		v[i].push_back(1);
	}

	for(int j = nn; j > 1; j >>= 1){
		int hn = j >> 1;
		for(int i = 0; i < hn; ++i){
			pro(v[i], v[i + hn], v[i]);
		}
	}

	return v[0][r];
}

int fac[N], ifac[N], inv[N];

void prencr(){
	fac[0] = ifac[0] = inv[1] = 1;
    for(int i = 2; i < N; ++i)
    	inv[i] = mod - 1LL * (mod / i) * inv[mod % i] % mod;
    for(int i = 1; i < N; ++i){
    	fac[i] = 1LL * i * fac[i - 1] % mod;
    	ifac[i] = 1LL * inv[i] * ifac[i - 1] % mod;
    }
}

int C(int n, int r){
	return (r >= 0 && n >= r) ? (1LL * fac[n] * ifac[n - r] % mod * ifac[r] % mod) : 0;
}

int main(){
	prencr();
	int n, p, q;
	cin >> n >> p >> q;
	ll ans = C(p + q - 2, p - 1);
	ans *= S(n - 1, p + q - 2);
	ans %= mod;
	cout << ans;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define pb push_back
const int N = 400004;

int n;
vector<int> e[N];
int sz[N], par[N], sp[30][N];
int V[N], L[N], CS[N];
bool mark[N];

struct tri {
	long long A, B;
	int C;
};

map<int, tri> nmp[N];

long long D[N]; // Sum of Distances
long long S[N]; // Sum of Depth
int T[N]; // Count

//======================================PRE-PROCESS=========================================

void getLevel(int u, int p = -1){
	sp[0][u] = p;
	for(auto x : e[u]) if(x != p) {
		L[x] = 1 + L[u];
		getLevel(x, u);
	}
}

void prepAncestor(){
	for(int i = 1; (1 << i) <= n; ++i) {
		for(int j = 1; j <= n; ++j) {
			sp[i][j] = sp[i - 1][sp[i - 1][j]];
		}
	}
}

int dist(int u, int v){
	if(L[u] < L[v]) swap(u, v);
	int lgn = 0;
	while((1 << lgn) < n) lgn++;
	int ans = 0;
	for(int i = lgn; i >= 0; --i){
		if(L[u] - (1 << i) >= L[v]){
			u = sp[i][u];
			ans += (1 << i);
		}
	}
	if(u == v) return ans;
	for(int i = lgn; i >= 0; --i){
		if(sp[i][u] != sp[i][v]){
			ans += 1 << (i + 1);
			u = sp[i][u];
			v = sp[i][v];
		}
	}
	return ans + 2;
}

//=================================CENTROID DECOMPOSITION===================================

void getSize(int u, int p = -1) {
      sz[u] = 1;
      for(auto v : e[u]) if(v != p && !mark[v]) {
            getSize(v, u);
            sz[u] += sz[v];
      }
}

int getCentroid(int u, int p, int lim) {
      for(auto v : e[u]) if(v != p && !mark[v] && sz[v] > lim) {
            return getCentroid(v, u, lim);
      }
      return u;
}

void decompose(int u, int p = -1) {
      getSize(u);
      int cen = getCentroid(u, -1, sz[u] / 2);
      par[cen] = p == -1 ? cen : p;
      mark[cen] = true;

      for(auto v : e[cen]) if(v != p && !mark[v]) {
            decompose(v, cen);
      }
}

//==========================================QUERY-HANDLER===============================================

void updAns(int u, int add) {

	int Z = V[u];

	tri tY = nmp[u][Z];
	ll ret = tY.A;
	int y = u, x = par[u];
	while(y != x) {
		tri tX = nmp[x][Z];
		ret += 1LL * (tX.C - tY.C) * dist(x, u) + (tX.A - tY.B);
		y = x;
		tY = tX;
		x = par[x];
	}
	ret <<= 1;

	int mul = add ? 1 : -1;
	D[Z] += mul * ret;
	S[Z] += mul * L[u];
	T[Z] += mul;
}

void updTree(int u, bool add) {
	int Z = V[u];
	int mul = add ? 1 : -1;
	for(int x = u; ; x = par[x]) {
		tri &tX = nmp[x][Z];
		tX.C += mul;
		if(!tX.C) {
			nmp[x].erase(Z);
		} else {
			tX.A += mul * dist(u, x);
			tX.B += mul * dist(u, par[x]);
		}
		if(x == par[x]) break;
	}
}

void upd(int u, bool add) {
	if(add) {
		updTree(u, add);
		updAns(u, add);
	} else {
		updAns(u, add);
		updTree(u, add);
	} 
}

//=========================================MAIN============================================

int main(){

	int m, q, ac;
	scanf("%d %d %d %d", &n, &m, &q, &ac);

	for(int i = 1; i <= n; ++i) {
		scanf("%d", &V[i]);
	}

	for(int i = 2; i <= n; ++i) {
		int v;
		scanf("%d", &v);
		e[v].pb(i);
		e[i].pb(v);
	}

	for(int i = 1; i <= m; ++i) {
		scanf("%d", &CS[i]);
	}

	L[1] = 1;
	getLevel(1);
	prepAncestor();
	decompose(1);

	for(int i = 1; i <= n; ++i) {
		upd(i, true);
	}

	while(q--) {
		int t;
		scanf("%d", &t);
		if(t == 1) {
			int u, v;
			scanf("%d %d", &u, &v);
			upd(u, false);
			V[u] = v; 
			upd(u, true);
		}
		else if(t == 2) {
			int v;
			scanf("%d", &v);
			long double ans = S[v] * T[v] - D[v] / 2;

			ans *= 1LL * CS[v] * CS[v];


			ans += 1LL * n * ac * ac;


			long long anst = 2LL * CS[v] * ac * S[v];

			ans -= anst;

			cout << fixed << setprecision(12) << ans / n << "\n"; 
		}
	}
}
